1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface Damage {
13	  itemType: string;
14	  amount: number;
15	}
16	
17	export interface Incident {
18	  cause: string;
19	  damages: Damage[];
20	}
21	
22	export interface QuoteStep {
23	  op: "quote";
24	  items: Item[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioResult {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	
57	// One row per item type the office recognises. Base premium (what it costs to
58	// insure) and insurance value (what it is insured FOR) are independent numbers,
59	// but they are known for exactly the same set of types — so they belong in one
60	// table. Keeping them apart would leave two key sets that must agree with
61	// nothing enforcing it.
62	interface ItemSpec {
63	  basePremium: number;
64	  insuranceValue: number;
65	  isComponent: boolean;
66	}
67	
68	const ITEM_SPECS = {
69	  sword: { basePremium: 100, insuranceValue: 1000, isComponent: false },
70	  amulet: { basePremium: 60, insuranceValue: 600, isComponent: false },
71	  staff: { basePremium: 80, insuranceValue: 800, isComponent: false },
72	  potion: { basePremium: 40, insuranceValue: 400, isComponent: false },
73	  rune: { basePremium: 25, insuranceValue: 250, isComponent: true },
74	  moonstone: { basePremium: 25, insuranceValue: 250, isComponent: true },
75	} as const satisfies Record<string, ItemSpec>;
76	
77	type KnownItemType = keyof typeof ITEM_SPECS;
78	
79	const isKnownItemType = (type: string): type is KnownItemType =>
80	  type in ITEM_SPECS;
81	
82	// The office insures only what its price list names. An unknown type has no
83	// premium and no insurance value, so there is nothing to quote — the whole
84	// scenario is rejected rather than priced at zero.
85	const specForItem = (item: Item): ItemSpec => {
86	  if (!isKnownItemType(item.type)) {
87	    throw new Error(`The MHPCO does not insure items of type ${item.type}`);
88	  }
89	  return ITEM_SPECS[item.type];
90	};
91	
92	const basePremiumForItem = (item: Item): number => specForItem(item).basePremium;
93	
94	const BLOCK_SIZE = 3;
95	
96	const BLOCK_BASE_PREMIUM = 60;
97	
98	const sum = (amounts: number[]): number =>
99	  amounts.reduce((total, amount) => total + amount, 0);
100	
101	// "Alike" means the same exact type, not merely the same family: two runes and
102	// a moonstone are three components but not three alike ones, so grouping them
103	// by type keeps them apart and denies them the block price.
104	const groupByType = (items: Item[]): Item[][] => {
105	  const groups = new Map<string, Item[]>();
106	  for (const item of items) {
107	    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
108	  }
109	  return [...groups.values()];
110	};
111	
112	// A block is three alike COMPONENTS — the discount is offered on runes and
113	// moonstones, not on swords. It is also not carved out of a larger group: the
114	// price applies only when the group holds exactly three (7 runes cost 7 × 25,
115	// not 60 + 60 + 25). Alikeness is guaranteed by the caller, which only ever
116	// passes a single group from groupByType.
117	const isComponent = (item: Item): boolean => specForItem(item).isComponent;
118	
119	const isBlock = (group: Item[]): boolean =>
120	  group.length === BLOCK_SIZE && group.every(isComponent);
121	
122	const basePremiumForGroup = (group: Item[]): number =>
123	  isBlock(group) ? BLOCK_BASE_PREMIUM : sum(group.map(basePremiumForItem));
124	
125	const basePremiumForItems = (items: Item[]): number =>
126	  sum(groupByType(items).map(basePremiumForGroup));
127	
128	const CURSE_SURCHARGE = 0.5;
129	
130	// Every modifier is an additive percentage of its OWN base — modifiers never
131	// compound with each other. Item-scoped modifiers take the affected item's base
132	// premium as their base; policy-scoped modifiers take the policy base premium
133	// (the sum of all item base premiums). So the total is always
134	// base + Σ (rate × that modifier's base), never a product of (1 + rate) factors.
135	const modifierAmount = (rate: number, base: number): number => rate * base;
136	
137	const ENCHANTMENT_SURCHARGE = 0.3;
138	
139	const ENCHANTMENT_SURCHARGE_LEVEL = 5;
140	
141	const isCursed = (item: Item): boolean => item.cursed === true;
142	
143	const attractsEnchantmentSurcharge = (item: Item): boolean =>
144	  (item.enchantment ?? 0) >= ENCHANTMENT_SURCHARGE_LEVEL;
145	
146	interface ItemModifier {
147	  rate: number;
148	  appliesTo: (item: Item) => boolean;
149	}
150	
151	// Each item-scoped modifier is a row: a rate and the condition under which it
152	// applies. The predicate names the modifier, so a row needs no separate label.
153	// Adding a modifier means adding a row, not a new branch.
154	const ITEM_MODIFIERS: ItemModifier[] = [
155	  { rate: CURSE_SURCHARGE, appliesTo: isCursed },
156	  { rate: ENCHANTMENT_SURCHARGE, appliesTo: attractsEnchantmentSurcharge },
157	];
158	
159	const itemModifierRates = (item: Item): number[] =>
160	  ITEM_MODIFIERS.filter((modifier) => modifier.appliesTo(item)).map(
161	    (modifier) => modifier.rate,
162	  );
163	
164	const LOYALTY_DISCOUNT = 0.2;
165	
166	const LOYALTY_THRESHOLD_YEARS = 2;
167	
168	const isLongStanding = (customer: Customer): boolean =>
169	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
170	
171	// Discounts are surcharges with the sign flipped: expressing one as a negative
172	// rate lets it flow through the same additive sum as every surcharge, with no
173	// separate subtraction step. Discount constants stay positive magnitudes and
174	// are negated here, at the point of use, so the direction is visible in the
175	// rate list rather than buried in a constant's sign.
176	const asDiscount = (rate: number): number => -rate;
177	
178	const INITIAL_ASSESSMENT_SURCHARGE = 0.1;
179	
180	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
181	
182	// Policy-scoped modifiers apply to the policy base premium. Unlike item
183	// modifiers they select on the customer and on the quote's position in the
184	// scenario rather than on an item.
185	//
186	// The initial-assessment surcharge applies to every quote: each item is treated
187	// as a first insurance regardless of customer history. The follow-up discount
188	// is what distinguishes a customer's later contracts.
189	const policyModifierRates = (
190	  customer: Customer,
191	  isFollowUpContract: boolean,
192	): number[] => [
193	  INITIAL_ASSESSMENT_SURCHARGE,
194	  ...(isLongStanding(customer) ? [asDiscount(LOYALTY_DISCOUNT)] : []),
195	  ...(isFollowUpContract ? [asDiscount(FOLLOW_UP_CONTRACT_DISCOUNT)] : []),
196	];
197	
198	const itemModifiersTotal = (items: Item[]): number =>
199	  sum(
200	    items.flatMap((item) =>
201	      itemModifierRates(item).map((rate) =>
202	        modifierAmount(rate, basePremiumForItem(item)),
203	      ),
204	    ),
205	  );
206	
207	const policyModifiersTotal = (
208	  policyBasePremium: number,
209	  customer: Customer,
210	  isFollowUpContract: boolean,
211	): number =>
212	  sum(
213	    policyModifierRates(customer, isFollowUpContract).map((rate) =>
214	      modifierAmount(rate, policyBasePremium),
215	    ),
216	  );
217	
218	// All amounts are rounded to whole G in the MHPCO's favour. Which way that
219	// points depends on which way the money flows: a premium comes in, so it rounds
220	// up; a payout goes out, so it rounds down.
221	//
222	// Two functions rather than one taking a direction, so that knowing which way
223	// favour points for a given kind of money stays here. A direction parameter
224	// would push that back onto every caller — the one thing these exist to answer.
225	const roundPremiumInMHPCOsFavour = (amount: number): number =>
226	  Math.ceil(amount);
227	
228	const roundPayoutInMHPCOsFavour = (amount: number): number =>
229	  Math.floor(amount);
230	
231	const quotePremium = (
232	  items: Item[],
233	  customer: Customer,
234	  isFollowUpContract: boolean,
235	): number => {
236	  const policyBasePremium = basePremiumForItems(items);
237	  return roundPremiumInMHPCOsFavour(
238	    policyBasePremium +
239	      itemModifiersTotal(items) +
240	      policyModifiersTotal(policyBasePremium, customer, isFollowUpContract) +
241	      PROCESSING_FEE,
242	  );
243	};
244	
245	const insuranceValueForItem = (item: Item): number =>
246	  specForItem(item).insuranceValue;
247	
248	// Deliberately NOT the shape of basePremiumForItems. Both aggregate a per-item
249	// figure from ITEM_SPECS, but the premium side groups by type first so a block
250	// of three alike components can be priced as one; this side never groups. Three
251	// runes cost 60 to insure and are insured for 3 × 250 = 750. The block is a
252	// discount on the price of cover, not a reduction of the cover bought.
253	//
254	// So the near-symmetry is a false friend: factoring the two into one traversal
255	// would read as tidier and would silently make blocks shrink the insurance sum.
256	// The repetition of `sum(items.map(...))` is the price of keeping them free to
257	// diverge, and is paid on purpose.
258	const insuranceSum = (items: Item[]): number =>
259	  sum(items.map(insuranceValueForItem));
260	
261	const CAP_MULTIPLE = 2;
262	
263	// The cap is twice the insurance sum — the value the items are insured FOR, so
264	// it is computed from the items alone and never from the premium. Curses,
265	// enchantments and loyalty change what a policy costs without changing what it
266	// covers (as do blocks — see insuranceSum). Naming the relation keeps that
267	// separation visible at the one place a policy is created.
268	const capForItems = (items: Item[]): number =>
269	  CAP_MULTIPLE * insuranceSum(items);
270	
271	const DEDUCTIBLE = 100;
272	
273	interface Policy {
274	  items: Item[];
275	  remainingCap: number;
276	}
277	
278	// Steps are not independent: a quote's premium depends on how many quotes came
279	// before it, and a claim draws down the cap of a policy an earlier quote
280	// created. So a step is a function from state to (result, next state), and the
281	// scenario is a fold over that — not a map, which would promise an independence
282	// the steps do not have.
283	//
284	// Policies are keyed by the index of the quote step that created them: a claim
285	// step names its policy by that zero-based index.
286	interface ScenarioState {
287	  quotesSoFar: number;
288	  policies: Map<number, Policy>;
289	}
290	
291	// A fresh state per run, not a shared constant. The Map makes the difference:
292	// a module-level seed would hand every scenario the same one. Nothing mutates
293	// it today — withPolicy copies before it writes — so a shared seed would work,
294	// but only by an invariant that lives in another function and would have to be
295	// rediscovered by the next writer. Building the seed per run makes each
296	// scenario's independence a property of the code rather than a promise about it.
297	const initialState = (): ScenarioState => ({
298	  quotesSoFar: 0,
299	  policies: new Map(),
300	});
301	
302	interface StepOutcome {
303	  result: StepResult;
304	  state: ScenarioState;
305	}
306	
307	// Both operations end by filing a policy under its quote's index — a claim
308	// re-files the same policy with a drawn-down cap. Naming that once keeps the
309	// Map out of the operations, so neither has to know how policies are stored.
310	const withPolicy = (
311	  state: ScenarioState,
312	  policyIndex: number,
313	  policy: Policy,
314	): ScenarioState => ({
315	  ...state,
316	  policies: new Map(state.policies).set(policyIndex, policy),
317	});
318	
319	// What makes a contract a follow-up is that the customer has already been
320	// quoted in this scenario — the first quote is the initial contract, every
321	// later one follows it. Named because the bare comparison is the
322	// follow-up-contract rule itself, not an index check: it is what decides
323	// whether the 15 % discount applies.
324	const isFollowUpContract = (state: ScenarioState): boolean =>
325	  state.quotesSoFar > 0;
326	
327	const runQuote = (
328	  step: QuoteStep,
329	  customer: Customer,
330	  state: ScenarioState,
331	  stepIndex: number,
332	): StepOutcome => ({
333	  result: {
334	    premium: quotePremium(step.items, customer, isFollowUpContract(state)),
335	  },
336	  state: withPolicy(
337	    { ...state, quotesSoFar: state.quotesSoFar + 1 },
338	    stepIndex,
339	    {
340	      items: step.items,
341	      remainingCap: capForItems(step.items),
342	    },
343	  ),
344	});
345	
346	const REDUCED_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
347	
348	const REDUCED_REIMBURSEMENT_RATE = 0.5;
349	
350	const FULL_REIMBURSEMENT_RATE = 1;
351	
352	// Reads enchantment like the premium-side surcharge rule, but is a different
353	// rule with its own level: this one halves what a claim pays out, that one
354	// raises what a policy costs. Sharing a predicate would tie two levels that the
355	// spec lets move independently, so the shape is repeated deliberately.
356	const qualifiesForReducedReimbursement = (item: Item): boolean =>
357	  (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_ENCHANTMENT_LEVEL;
358	
359	// The reimbursement rate is decided first, then one deductible comes off.
360	//
361	// The dragon-material clause is absent on purpose, not by oversight. It promises
362	// full reimbursement of the damage before the deductible — which is exactly what
363	// FULL_REIMBURSEMENT_RATE already gives every item that misses the reduced-rate
364	// clause. Where both clauses apply the spec awards it to the 50 % rule. Between
365	// them the two facts leave the clause with no input it can move: dragon material
366	// at enchantment 9 or 8 pays the same 400 as steel at those levels, and at
367	// enchantment 5 it pays the same 700 steel would. Writing it as its own branch
368	// would add a branch no test could ever tell from the default — a distinction
369	// the domain does not make.
370	const reimbursementRate = (item: Item): number =>
371	  qualifiesForReducedReimbursement(item)
372	    ? REDUCED_REIMBURSEMENT_RATE
373	    : FULL_REIMBURSEMENT_RATE;
374	
375	const payoutForDamage = (damage: Damage, item: Item): number =>
376	  damage.amount * reimbursementRate(item) - DEDUCTIBLE;
377	
378	// Returns AN insured item of the damaged type, not THE damaged one — a policy
379	// can cover two swords, so the type does not name a unique item. Two damage
380	// entries of the same type are both answered with the same first match.
381	//
382	// That is sound today because the answer is used solely to read payout
383	// attributes (the reimbursement rate), and the covered case — two damages
384	// against two swords — insures identical swords, which read the same either
385	// way. The deductible is charged per damage entry, not per matched item, so
386	// counting is unaffected too.
387	//
388	// One thing would break it, not yet under test: two swords with DIFFERENT
389	// attributes (say enchantment 3 and 9). Both damages would take the first
390	// sword's rate; the second should take its own. This lookup must then become a
391	// pairing that consumes what it matches. The honest name marks that spot.
392	//
393	// The `!` is a proof, not an assumption: rejectUnmatchedDamages runs first and
394	// throws unless every claimed type is covered at least as many times as it is
395	// named — so by the time this runs, a match exists for every damage entry. Both
396	// ways it could fail are covered by tests: claiming a type more often than it is
397	// insured, and claiming a type the policy does not cover at all.
398	const anInsuredItemOfDamagedType = (policy: Policy, damage: Damage): Item =>
399	  policy.items.find((item) => item.type === damage.itemType)!;
400	
401	// Counts how many times each value occurs. Deliberately typed on strings rather
402	// than on Item: the guard below tallies two different things (item types held
403	// and item types named by damages) and only their counts are ever compared, so
404	// the tally has no business knowing what the strings mean.
405	const tally = (values: string[]): Map<string, number> => {
406	  const counts = new Map<string, number>();
407	  for (const value of values) {
408	    counts.set(value, (counts.get(value) ?? 0) + 1);
409	  }
410	  return counts;
411	};
412	
413	// Every damage entry must claim an insured item of its own, so a type cannot be
414	// damaged more times than the policy covers it. One rule, three error cases the
415	// spec states separately — all of them the same comparison at different counts:
416	//
417	//   claimed > insured, insured ≥ 1  a type damaged more often than it is insured
418	//   claimed > insured, insured = 0  a type the policy does not cover at all
419	//   claimed > insured, insured = 0  a type the office does not insure at all
420	//
421	// The last two differ only in why the count is zero, which is why neither needs
422	// its own test. An uninsured type and an unknown type are both covered 0 times
423	// against a claimed 1. In particular the unknown type never reaches a lookup in
424	// ITEM_SPECS: a broomstick is not in THIS policy, which is the more precise
425	// complaint than whether the office insures broomsticks in general. The quote
426	// path is where the price list is consulted and where an unknown type is
427	// rejected as uninsurable.
428	//
429	// Checked before any payout is computed: the spec rejects the whole claim, not
430	// just the surplus entries.
431	const rejectUnmatchedDamages = (policy: Policy, incident: Incident): void => {
432	  const insured = tally(policy.items.map((item) => item.type));
433	  const claimed = tally(incident.damages.map((damage) => damage.itemType));
434	  for (const [type, claimedCount] of claimed) {
435	    const insuredCount = insured.get(type) ?? 0;
436	    if (claimedCount > insuredCount) {
437	      throw new Error(
438	        `Policy covers ${insuredCount} ${type}(s) but the claim names ${claimedCount}`,
439	      );
440	    }
441	  }
442	};
443	
444	// A damage is what an incident cost the owner, so it cannot be negative. Zero
445	// is left alone: the spec forbids only negative amounts, and a zero damage
446	// simply pays nothing once the deductible bites.
447	const isNegative = (damage: Damage): boolean => damage.amount < 0;
448	
449	const rejectNegativeDamages = (incident: Incident): void => {
450	  const negative = incident.damages.find(isNegative);
451	  if (negative) {
452	    throw new Error(
453	      `Damage to ${negative.itemType} is negative: ${negative.amount}`,
454	    );
455	  }
456	};
457	
458	// Both guards run before any payout is computed: the spec rejects the whole
459	// claim, not just the offending entries, so a valid entry alongside an invalid
460	// one must not be paid.
461	//
462	// They are two statements rather than a list of validations. Their signatures
463	// differ (only the first needs the policy), so a uniform list could hold them
464	// only by giving the second a parameter it ignores. And the order is not
465	// incidental: rejectUnmatchedDamages must come first because it is what makes
466	// the lookup in anInsuredItemOfDamagedType total — an obligation that reads as
467	// a sequenced line here but would vanish into array order in a list.
468	//
469	// Two is the whole set, not a stage on the way to more. The spec's remaining
470	// claim-side error — a damage naming an item type the office does not insure —
471	// needs no guard of its own: rejectUnmatchedDamages already catches it, because
472	// a type the office does not insure cannot be in the policy either and so is
473	// covered zero times. See its comment for why that is the more precise
474	// diagnosis rather than a lucky accident.
475	const payoutForIncident = (policy: Policy, incident: Incident): number => {
476	  rejectUnmatchedDamages(policy, incident);
477	  rejectNegativeDamages(incident);
478	  return sum(
479	    incident.damages.map((damage) =>
480	      payoutForDamage(damage, anInsuredItemOfDamagedType(policy, damage)),
481	    ),
482	  );
483	};
484	
485	// The damage decides what a claim is WORTH; the cap decides what there is left
486	// to pay it WITH. Once the cap is spent the office pays what remains, not what
487	// was asked — so the cap bounds the payout before it is charged against it.
488	//
489	// This is the guarantee that makes drawDownCap's subtraction safe: a payout that
490	// has passed through here can never exceed the balance, so the balance can never
491	// go negative. The two are a pair — bound, then spend — and neither is sound
492	// without the other.
493	const payoutWithinCap = (payout: number, remainingCap: number): number =>
494	  Math.min(payout, remainingCap);
495	
496	// A policy's cap is a balance, not a per-claim limit: each claim spends part of
497	// it and the rest carries forward to the next claim against the same policy.
498	// The balance stays non-negative because payoutWithinCap has already bounded
499	// what is spent — this subtraction does not defend itself, it relies on that.
500	//
501	// Naming the draw-down separates what the cap DOES from how a claim is assembled
502	// — the one line in runClaim that was arithmetic rather than plumbing.
503	const drawDownCap = (remainingCap: number, payout: number): number =>
504	  remainingCap - payout;
505	
506	const runClaim = (step: ClaimStep, state: ScenarioState): StepOutcome => {
507	  // A claim naming a policy that does not exist is a spec error case, but no
508	  // test drives it yet. The assertion stands in until one does — at which point
509	  // the missing case becomes the error branch rather than a crash.
510	  const policy = state.policies.get(step.policy)!;
511	  // Rounded before the clamp so the cap is only ever compared with, and reduced
512	  // by, whole G — a fractional payout would otherwise leave a fractional cap
513	  // behind for the next claim.
514	  const claimWorth = roundPayoutInMHPCOsFavour(
515	    payoutForIncident(policy, step.incident),
516	  );
517	  const payout = payoutWithinCap(claimWorth, policy.remainingCap);
518	  const remainingCap = drawDownCap(policy.remainingCap, payout);
519	  return {
520	    result: { payout, remainingCap },
521	    state: withPolicy(state, step.policy, { ...policy, remainingCap }),
522	  };
523	};
524	
525	// Dispatch decides once what a step is; each operation then owns both its
526	// result and how it advances the state, so no caller has to re-test step.op to
527	// know what the step did.
528	const runStep = (
529	  step: Step,
530	  customer: Customer,
531	  state: ScenarioState,
532	  stepIndex: number,
533	): StepOutcome =>
534	  step.op === "quote"
535	    ? runQuote(step, customer, state, stepIndex)
536	    : runClaim(step, state);
537	
538	// The fold carries both halves of the outcome: the results accumulated so far
539	// and the state the next step will see. Threading the state explicitly (rather
540	// than recovering it from the last result) keeps the dependency between steps
541	// visible in the type.
542	interface ScenarioRun {
543	  results: StepResult[];
544	  state: ScenarioState;
545	}
546	
547	const initialRun = (): ScenarioRun => ({ results: [], state: initialState() });
548	
549	const appendStep =
550	  (customer: Customer) =>
551	  (run: ScenarioRun, step: Step, stepIndex: number): ScenarioRun => {
552	    const outcome = runStep(step, customer, run.state, stepIndex);
553	    return {
554	      results: [...run.results, outcome.result],
555	      state: outcome.state,
556	    };
557	  };
558	
559	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => ({
560	  results: steps.reduce(appendStep(customer), initialRun()).results,
561	});
